"""建造页面 UI 控制器。

已完成，需测试

覆盖游戏 **建造** 页面及其标签组 (建造/解体/开发/废弃) 的交互。

页面入口:
    主页面 → 侧边栏 → 建造

标签组:
    建造/解体/开发/废弃 四个标签共享相同的顶部导航栏。
    切换标签不会离开此页面组，只是改变内容区域。

坐标体系:
    所有坐标为相对值 (0.0-1.0)。

使用方式::

    from autowsgr.ui.build_page import BuildPage, BuildTab

    page = BuildPage(ctrl)
    page.switch_tab(BuildTab.DEVELOP)
    page.go_back()
"""

from __future__ import annotations

import enum
from typing import TYPE_CHECKING

from autowsgr.image_resources import Templates
from autowsgr.infra.exceptions import PageDriftError
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName, ShipType
from autowsgr.ui._checkers import confirm_dialog_visible, screen_changed
from autowsgr.ui.stack import record_page_substate
from autowsgr.ui.substate import SubstateSpec
from autowsgr.ui.utils import (
    NavConfig,
    NavigationError,
    click_and_wait_for_page,
    click_and_wait_leave_page,
    wait_for_page,
    wait_for_stable_screen,
)
from autowsgr.vision import ImageChecker, PageMatch

from .tabbed_page import (
    TabbedPageType,
    check_tabbed_page,
    get_active_tab_index,
    make_tab_checker,
)


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.context import GameContext


_log = get_logger('ui')

_RESULT_MARKERS = (Templates.Symbol.GET_SHIP, Templates.Symbol.GET_ITEM)
"""建造/开发完成后的结果标记 (获取舰船 / 获取装备)。"""

_STEP_CONFIG = NavConfig(
    max_retries=1,
    retry_delay=0.0,
    timeout=3.0,
    interval=0.25,
    stable_frames=1,
)
"""中间步骤的闭环配置：只点一次，失败不重试 (避免误触下一层 UI)。"""


def _result_marker_visible(screen: np.ndarray) -> bool:
    """当前画面是否仍停留在建造获取结果。"""
    return ImageChecker.template_exists(screen, _RESULT_MARKERS)


# ═══════════════════════════════════════════════════════════════════════════════
# 枚举
# ═══════════════════════════════════════════════════════════════════════════════


class BuildTab(enum.Enum):
    """建造页面标签组。"""

    BUILD = '建造'
    DESTROY = '解体'
    DEVELOP = '开发'
    DISCARD = '废弃'


# ═══════════════════════════════════════════════════════════════════════════════
# 标签索引映射
# ═══════════════════════════════════════════════════════════════════════════════

_TAB_LIST: list[BuildTab] = list(BuildTab)
"""标签枚举值列表 — 索引与标签栏探测位置一一对应。"""

_TAB_TO_INDEX: dict[BuildTab, int] = {tab: i for i, tab in enumerate(_TAB_LIST)}
"""标签 → 标签索引映射。"""


# ═══════════════════════════════════════════════════════════════════════════════
# 点击坐标
# ═══════════════════════════════════════════════════════════════════════════════

CLICK_BACK: tuple[float, float] = (0.022, 0.058)
"""回退按钮 (◁)。"""

CLICK_TAB: dict[BuildTab, tuple[float, float]] = {
    BuildTab.BUILD: (0.1875, 0.0463),
    BuildTab.DESTROY: (0.3125, 0.0463),
    BuildTab.DEVELOP: (0.4375, 0.0463),
    BuildTab.DISCARD: (0.5625, 0.0463),
}
"""标签切换点击坐标。

.. note::
    坐标为估计值 (TODO: 待实际截图确认)。
"""

# ── 建造槽位 ──

BUILD_SLOT_POSITIONS: list[tuple[float, float]] = [
    (0.823, 0.312),
    (0.823, 0.508),
    (0.823, 0.701),
    (0.823, 0.898),
]
"""4 个建造槽位的中心点 (start/complete/fast 按钮位置)。"""

CLICK_CONFIRM_BUILD: tuple[float, float] = (0.89, 0.89)
"""确认建造按钮。"""

# ── 解体标签操作 ──

CLICK_DESTROY_ADD: tuple[float, float] = (0.0938, 0.3815)
"""解体 — 点击「添加」按钮。旧代码: timer.click(90, 206)"""

CLICK_DESTROY_QUICK_SELECT: tuple[float, float] = (0.91, 0.3)
"""解体 — 快速选择按钮。"""

CLICK_DESTROY_CONFIRM_SELECT: tuple[float, float] = (0.915, 0.906)
"""解体 — 确认选择。"""

CLICK_DESTROY_REMOVE_EQUIP: tuple[float, float] = (0.837, 0.646)
"""解体 — 卸下装备复选框。"""

CLICK_DESTROY_CONFIRM: tuple[float, float] = (0.9, 0.9)
"""解体 — 解装确认按钮。"""

CLICK_DESTROY_FOUR_STAR_CONFIRM: tuple[float, float] = (0.38, 0.567)
"""解体 — 四星确认弹窗。"""

CLICK_DESTROY_TYPE_FILTER: tuple[float, float] = (0.912, 0.681)
"""解体 — 打开舰船类型过滤器。"""

CLICK_DESTROY_CONFIRM_FILTER: tuple[float, float] = (0.9, 0.85)
"""解体 — 确认舰船类型过滤。"""

# ── 建造获取动画 ──

CLICK_DISMISS_ANIMATION: tuple[float, float] = (0.9531, 0.9537)
"""点击跳过建造获取动画。旧代码: timer.click(915, 515)"""


# ═══════════════════════════════════════════════════════════════════════════════
# 页面控制器
# ═══════════════════════════════════════════════════════════════════════════════


class BuildPage:
    """建造页面控制器 (含 解体/开发/废弃 标签组)。

    Parameters
    ----------
    ctrl:
        Android 设备控制器实例。
    """

    def __init__(self, ctx: GameContext) -> None:
        self._ctx = ctx
        self._ctrl = ctx.ctrl

    # ── 页面识别 ──────────────────────────────────────────────────────────

    @staticmethod
    def is_current_page(screen: np.ndarray) -> PageMatch:
        """判断截图是否为建造页面组 (含全部 4 个标签)。

        通过统一标签页检测层识别,返回带覆盖度分数的 PageMatch。

        Parameters
        ----------
        screen:
            截图 (HxWx3, RGB)。
        """
        return check_tabbed_page(screen, TabbedPageType.BUILD)

    @staticmethod
    def get_active_tab(screen: np.ndarray) -> BuildTab | None:
        """获取当前激活的标签。

        Parameters
        ----------
        screen:
            截图 (HxWx3, RGB)。

        Returns
        -------
        BuildTab | None
            当前标签，索引越界或无法确定时返回 ``None``。
        """
        idx = get_active_tab_index(screen)
        if idx is None or idx >= len(_TAB_LIST):
            return None
        return _TAB_LIST[idx]

    # ── 标签切换 ──────────────────────────────────────────────────────────

    _TAB_SWITCH_CONFIG = NavConfig(
        max_retries=2,
        retry_delay=0.4,
        timeout=3.0,
        interval=0.35,
        stable_frames=2,
    )
    """标签切换的闭环配置：点击后必须连续两帧识别到目标标签。"""

    def switch_tab(self, tab: BuildTab) -> None:
        """切换到指定标签并验证到达。

        点击后由 ``make_tab_checker`` 识别目标标签签名，连续两帧命中才算
        成功；超时抛 :class:`PageDriftError`（可恢复级），由上层决定重试。

        Parameters
        ----------
        tab:
            目标标签。

        Raises
        ------
        PageDriftError
            超时未到达目标标签。
        """
        current = self.get_active_tab(self._ctrl.screenshot())
        _log.info(
            '[UI] 建造页面: {} → {}',
            current.value if current else '未知',
            tab.value,
        )
        target_idx = _TAB_TO_INDEX[tab]
        source = f'建造-{current.value if current else "?"}'
        target = f'建造-{tab.value}'

        try:
            click_and_wait_for_page(
                self._ctrl,
                click_coord=CLICK_TAB[tab],
                checker=make_tab_checker(TabbedPageType.BUILD, target_idx),
                source=source,
                target=target,
                config=self._TAB_SWITCH_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError as exc:
            raise PageDriftError(
                f'建造标签切换失败: {source} -> {target}',
                target=target,
                page_trail=[source, target],
                action_trail=[f'switch_tab({tab.value})'],
                screen=self._ctrl.screenshot(),
            ) from exc

        record_page_substate(self._ctx, PageName.BUILD, tab.value)

    # ── 回退 ──────────────────────────────────────────────────────────────

    def go_back(self) -> None:
        """点击回退按钮 (◁)，返回侧边栏。

        Raises
        ------
        NavigationError
            超时仍在建造页面。
        """
        from autowsgr.ui.main_page import MainPage
        from autowsgr.ui.sidebar_page import SidebarPage

        _log.info('[UI] 建造页面 → 返回侧边栏')

        def _checker(screen: np.ndarray) -> bool:
            return SidebarPage.is_current_page(screen) or MainPage.is_current_page(screen)

        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_BACK,
            checker=_checker,
            source=PageName.BUILD,
            target=f'{PageName.SIDEBAR}/{PageName.MAIN}',
            stop_event=self._ctx.stop_event,
        )

    # ── 建造操作 ──────────────────────────────────────────────────────────

    def click_slot(self, slot: int) -> None:
        """点击建造槽位 (1-4)，并确认画面产生可见变化。

        Parameters
        ----------
        slot:
            槽位编号 (1-4)。
        """
        if not 1 <= slot <= 4:
            raise ValueError(f'建造槽位必须为 1-4，收到: {slot}')
        _log.info('[UI] 建造页面 → 点击槽位 {}', slot)
        self._click_with_effect(BUILD_SLOT_POSITIONS[slot - 1], source=f'建造-槽位{slot}')

    def collect_slot(self, slot: int) -> None:
        """收取指定槽位的已完成建造。

        点击槽位后等待结果画面稳定，再处理获取动画/确认弹窗。

        Parameters
        ----------
        slot:
            槽位编号 (1-4)。
        """
        _log.info('[UI] 建造页面 → 收取槽位 {}', slot)
        self.click_slot(slot)
        self._wait_stable(f'建造-收取槽位{slot}', timeout=2.0)
        self.dismiss_build_result()

    def fast_build_slot(self, slot: int) -> None:
        """对指定槽位使用快速建造。

        点击快速建造按钮后等待画面稳定，不再固定 sleep。

        Parameters
        ----------
        slot:
            槽位编号 (1-4)。
        """
        _log.info('[UI] 建造页面 → 快速建造槽位 {}', slot)
        self.click_slot(slot)
        self._wait_stable(f'建造-快速建造槽位{slot}', timeout=1.5)

    def start_build(self) -> None:
        """在当前标签下启动建造。

        点击一个空闲槽位的「开始建造」按钮后，
        等待资源选择页面，然后点击确认。

        .. note::
            资源配方调整（滑块操作）需要 ops 层配合 OCR 实现。
            此方法仅执行确认点击。
        """
        _log.info('[UI] 建造页面 → 确认建造')
        resource_tmpl = Templates.Build.RESOURCE
        SubstateSpec(
            page=PageName.BUILD.value,
            substate='建造队列',
            checker=lambda screen: (
                not ImageChecker.template_exists(screen, resource_tmpl)
                and self.is_current_page(screen).matched
            ),
            timeout=3.0,
            retries=1,
            interval=0.3,
            stable_frames=2,
        ).click(
            self._ctx,
            CLICK_CONFIRM_BUILD,
            source='建造-确认',
            action_name='start_build',
        )

    def dismiss_animation(self) -> None:
        """点击跳过建造获取动画，并确认结果标记消失。"""
        try:
            click_and_wait_leave_page(
                self._ctrl,
                CLICK_DISMISS_ANIMATION,
                _result_marker_visible,
                source='建造-跳过获取动画',
                target='结果标记消失',
                config=_STEP_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[UI] 建造获取动画: 点击后结果标记仍在, 交由确认弹窗处理')
        self._wait_stable('建造-获取动画', timeout=0.8)

    # ── 解体操作 ──────────────────────────────────────────────────────────

    def destroy_click_add(self) -> None:
        """解体标签 → 点击「添加」按钮。"""
        _log.info('[UI] 建造页面 (解体) → 添加')
        self._click_with_effect(CLICK_DESTROY_ADD, source='解体-添加', min_diff=1.0)

    def destroy_quick_select(self) -> None:
        """解体标签 → 点击「快速选择」按钮。"""
        _log.info('[UI] 建造页面 (解体) → 快速选择')
        self._click_with_effect(CLICK_DESTROY_QUICK_SELECT, source='解体-快速选择')

    def destroy_confirm_select(self) -> None:
        """解体标签 → 点击「确认选择」。"""
        _log.info('[UI] 建造页面 (解体) → 确认选择')
        self._click_with_effect(CLICK_DESTROY_CONFIRM_SELECT, source='解体-确认选择')

    def destroy_toggle_remove_equip(self) -> None:
        """解体标签 → 点击「卸下装备」复选框。"""
        _log.info('[UI] 建造页面 (解体) → 卸下装备')
        self._click_with_effect(CLICK_DESTROY_REMOVE_EQUIP, source='解体-卸下装备', min_diff=0.8)

    def destroy_confirm(self) -> None:
        """解体标签 → 点击「解装确认」，验证确认弹窗出现或画面已变化。"""
        _log.info('[UI] 建造页面 (解体) → 解装确认')
        before = self._ctrl.screenshot()
        changed = screen_changed(before, min_diff=1.5)
        try:
            click_and_wait_for_page(
                self._ctrl,
                CLICK_DESTROY_CONFIRM,
                lambda screen: confirm_dialog_visible(screen) or changed(screen),
                source='解体-解装确认',
                target='确认弹窗',
                config=_STEP_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[UI] 解体-解装确认: 点击后未确认弹窗出现, 不重试')

    def destroy_four_star_confirm(self) -> None:
        """解体标签 → 四星确认弹窗点击确认，并验证回到解体列表。

        四星提示是游戏自绘弹窗，没有独立模板；这里保留「点击四星确认」这一
        步（与旧流程一致），但把「点完就走」改成「等待回到解体列表」。
        若四星确认后还叠了一层通用确认弹窗，则补点一次并再次验证。
        """
        _log.info('[UI] 建造页面 (解体) → 四星确认')
        try:
            click_and_wait_for_page(
                self._ctrl,
                CLICK_DESTROY_FOUR_STAR_CONFIRM,
                self._is_destroy_list,
                source='解体-四星确认',
                target='解体列表',
                config=NavConfig(
                    max_retries=1,
                    retry_delay=0.0,
                    timeout=4.0,
                    interval=0.3,
                    stable_frames=2,
                ),
                stop_event=self._ctx.stop_event,
            )
        except NavigationError as exc:
            confirm = ImageChecker.find_any(
                self._ctrl.screenshot(), Templates.Confirm.all()
            )
            if confirm is not None:
                self._dismiss_confirm(confirm.center, source='解体-二次确认')
                if self._wait_destroy_list(timeout=2.0):
                    record_page_substate(self._ctx, PageName.BUILD, BuildTab.DESTROY.value)
                    return
            raise PageDriftError(
                '解体失败: 确认后未回到解体列表',
                target='解体列表',
                page_trail=['解体-四星确认', '解体列表'],
                action_trail=['destroy_four_star_confirm()'],
                screen=self._ctrl.screenshot(),
            ) from exc
        record_page_substate(self._ctx, PageName.BUILD, BuildTab.DESTROY.value)

    def destroy_open_type_filter(self) -> None:
        """解体标签 → 打开舰船类型过滤器。"""
        _log.info('[UI] 建造页面 (解体) → 打开类型过滤')
        self._click_with_effect(CLICK_DESTROY_TYPE_FILTER, source='解体-打开类型过滤')

    def destroy_confirm_filter(self) -> None:
        """解体标签 → 确认舰船类型过滤。"""
        _log.info('[UI] 建造页面 (解体) → 确认过滤')
        self._click_with_effect(CLICK_DESTROY_CONFIRM_FILTER, source='解体-确认过滤')

    # ── 闭环辅助 ──────────────────────────────────────────────────────────

    def _wait_stable(self, source: str, *, timeout: float = 1.2) -> None:
        wait_for_stable_screen(
            self._ctrl,
            timeout=timeout,
            interval=0.12,
            stable_frames=2,
            source=source,
            stop_event=self._ctx.stop_event,
        )

    def _click_with_effect(
        self,
        click_coord: tuple[float, float],
        *,
        source: str,
        min_diff: float = 1.5,
        timeout: float = 1.5,
    ) -> bool:
        """点击后验证画面确实变化；失败只点一次并 warning。"""
        before = self._ctrl.screenshot()
        try:
            click_and_wait_for_page(
                self._ctrl,
                click_coord,
                screen_changed(before, min_diff=min_diff),
                source=source,
                target=f'{source}/画面变化',
                config=NavConfig(
                    max_retries=1,
                    retry_delay=0.0,
                    timeout=timeout,
                    interval=0.2,
                    stable_frames=1,
                ),
                stop_event=self._ctx.stop_event,
            )
            return True
        except NavigationError:
            _log.warning('[UI] {}: 点击后未检测到画面变化, 不重试', source)
            return False

    def _is_destroy_list(self, screen: np.ndarray) -> bool:
        """解体列表就绪：仍在建造页、激活解体标签、且无确认弹窗。"""
        if not self.is_current_page(screen).matched:
            return False
        if self.get_active_tab(screen) != BuildTab.DESTROY:
            return False
        return not confirm_dialog_visible(screen)

    def _wait_destroy_list(self, *, timeout: float) -> bool:
        try:
            wait_for_page(
                self._ctrl,
                self._is_destroy_list,
                timeout=timeout,
                interval=0.2,
                stable_frames=1,
                source='解体',
                target='解体列表',
                stop_event=self._ctx.stop_event,
            )
            return True
        except NavigationError:
            return False

    def _dismiss_confirm(self, coord: tuple[float, float], *, source: str) -> None:
        """点击确认按钮并验证弹窗消失。"""
        try:
            click_and_wait_leave_page(
                self._ctrl,
                coord,
                confirm_dialog_visible,
                source=source,
                target='确认弹窗关闭',
                config=NavConfig(
                    max_retries=1,
                    retry_delay=0.0,
                    timeout=2.5,
                    interval=0.2,
                ),
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[UI] {}: 点击后确认弹窗仍在', source)
        self._wait_stable(source, timeout=0.8)

    # ── 组合动作 — 建造收取 ──

    def dismiss_build_result(self) -> None:
        """处理建造完成后获取舰船的动画/弹窗。

        每次点击跳过动画后都重新截图：结果标记消失即返回；仍有确认弹窗
        就用 :meth:`_dismiss_confirm` 验证弹窗关闭。连续两轮点击都没有
        改变画面时停止，避免在未知画面里连点。
        """
        stalled = 0
        for _ in range(10):
            screen = self._ctrl.screenshot()
            if not _result_marker_visible(screen):
                return
            before = screen
            self.dismiss_animation()
            screen = self._ctrl.screenshot()
            detail = ImageChecker.find_any(screen, Templates.Confirm.all())
            if detail is not None:
                self._dismiss_confirm(detail.center, source='建造-获取结果确认')
                stalled = 0
                continue
            if screen_changed(before, min_diff=1.0)(screen):
                stalled = 0
            else:
                stalled += 1
                if stalled >= 2:
                    _log.warning('[UI] 建造获取结果: 连续点击未改变画面, 停止重试')
                    return

    def collect_all(
        self,
        build_type: str = 'ship',
        *,
        allow_fast_build: bool = False,
    ) -> int:
        """收取已建造完成的舰船或装备。

        必须已在建造页面对应标签上。

        Returns
        -------
        int
            收取数量。

        Raises
        ------
        RuntimeError
            仓库已满。
        PageDriftError
            点击已完成的槽位后完成标记未消失。
        """
        collected = 0

        if allow_fast_build:
            fast_tmpl = (
                Templates.Build.SHIP_FAST if build_type == 'ship' else Templates.Build.EQUIP_FAST
            )
            for _ in range(4):
                screen = self._ctrl.screenshot()
                detail = ImageChecker.find_template(screen, fast_tmpl)
                if detail is None:
                    break
                self._click_with_effect(detail.center, source='建造-快速建造', min_diff=1.0)
                self._wait_stable('建造-快速建造确认', timeout=1.2)
                confirm = ImageChecker.find_any(
                    self._ctrl.screenshot(), Templates.Confirm.all()
                )
                if confirm is not None:
                    self._dismiss_confirm(confirm.center, source='建造-快速建造确认')

        complete_tmpl = (
            Templates.Build.SHIP_COMPLETE
            if build_type == 'ship'
            else Templates.Build.EQUIP_COMPLETE
        )
        full_depot_tmpl = (
            Templates.Build.SHIP_FULL_DEPOT
            if build_type == 'ship'
            else Templates.Build.EQUIP_FULL_DEPOT
        )

        for _ in range(4):
            screen = self._ctrl.screenshot()
            detail = ImageChecker.find_template(screen, complete_tmpl)
            if detail is None:
                break
            if ImageChecker.template_exists(screen, full_depot_tmpl):
                raise RuntimeError(f'{build_type} 仓库已满')
            try:
                click_and_wait_for_page(
                    self._ctrl,
                    detail.center,
                    lambda current, tmpl=complete_tmpl: (
                        _result_marker_visible(current)
                        or not ImageChecker.template_exists(current, tmpl)
                    ),
                    source=f'建造-收取 {build_type}',
                    target='获取结果/完成标记消失',
                    config=NavConfig(
                        max_retries=1,
                        retry_delay=0.0,
                        timeout=4.0,
                        interval=0.25,
                    ),
                    stop_event=self._ctx.stop_event,
                )
            except NavigationError as exc:
                raise PageDriftError(
                    f'建造收取失败: 点击后完成标记仍在 ({build_type})',
                    target='建造收取',
                    page_trail=[PageName.BUILD.value, '建造收取'],
                    action_trail=['collect_all()'],
                    screen=self._ctrl.screenshot(),
                ) from exc
            self._wait_stable('建造-收取结果', timeout=1.5)
            self.dismiss_build_result()
            collected += 1

        _log.info('[UI] 建造收取: {} 艘 ({})', collected, build_type)
        return collected

    def start_new_build(self, build_type: str = 'ship') -> None:
        """在当前标签启动一次新建造。

        「点击开始 → 资源选择页出现 → 确认 → 回到建造页」全部走
        :class:`~autowsgr.ui.substate.SubstateSpec`，不再固定 sleep。

        Raises
        ------
        RuntimeError
            建造队列已满。
        PageDriftError
            资源选择页未出现，或确认后未回到建造页。
        """
        start_tmpl = (
            Templates.Build.SHIP_START if build_type == 'ship' else Templates.Build.EQUIP_START
        )
        screen = self._ctrl.screenshot()
        detail = ImageChecker.find_template(screen, start_tmpl)
        if detail is None:
            raise RuntimeError(f'{build_type} 建造队列已满')

        resource_tmpl = Templates.Build.RESOURCE
        SubstateSpec(
            page=PageName.BUILD.value,
            substate='资源选择',
            checker=lambda screen: ImageChecker.template_exists(screen, resource_tmpl),
            timeout=5.0,
            retries=1,
            interval=0.3,
            stable_frames=1,
        ).click(
            self._ctx,
            detail.center,
            source=f'建造-资源选择 ({build_type})',
            action_name='start_new_build',
        )

        SubstateSpec(
            page=PageName.BUILD.value,
            substate='建造队列',
            checker=lambda screen: (
                not ImageChecker.template_exists(screen, resource_tmpl)
                and self.is_current_page(screen).matched
            ),
            timeout=3.0,
            retries=1,
            interval=0.3,
            stable_frames=2,
        ).click(
            self._ctx,
            CLICK_CONFIRM_BUILD,
            source=f'建造-确认 ({build_type})',
            action_name='confirm_build',
        )
        _log.info('[UI] 建造已启动 ({})', build_type)

    def destroy_ships(
        self,
        ship_types: list[ShipType] | None = None,
        *,
        remove_equipment: bool = True,
    ) -> None:
        """在解体标签上执行完整解装流程。

        Parameters
        ----------
        ship_types:
            要解体的舰种列表。
            ``None`` (默认) 表示不过滤舰种，直接快速选择全部。
            传入非空列表时，先打开舰种过滤器按舰种筛选，再执行后续操作。
        remove_equipment:
            是否在解装前卸下装备。默认 ``True``。
        """
        # 在任何 UI 操作前验证坐标，避免新增 OCR 舰种导致筛选中途失败。
        type_positions = [t.relative_position_in_destroy for t in ship_types or []]

        self.destroy_click_add()
        self._wait_stable('解体-添加后')

        if ship_types:
            # 按舰种过滤：打开过滤器 → 勾选各舰种 → 确认
            self.destroy_open_type_filter()
            self._wait_stable('解体-类型过滤器')
            for ship_type, position in zip(ship_types, type_positions, strict=True):
                _log.debug('[UI] 解体 → 点击舰种: {}', ship_type.value)
                self._click_with_effect(
                    position,
                    source=f'解体-舰种 {ship_type.value}',
                    min_diff=0.8,
                )
            self.destroy_confirm_filter()
            self._wait_stable('解体-确认过滤')

        self.destroy_quick_select()
        self._wait_stable('解体-快速选择')
        self.destroy_confirm_select()
        self._wait_stable('解体-确认选择')
        if remove_equipment:
            self.destroy_toggle_remove_equip()
            self._wait_stable('解体-卸下装备', timeout=0.8)
        self.destroy_confirm()
        self._wait_stable('解体-解装确认')
        self.destroy_four_star_confirm()

        _log.info(
            '[UI] 解装完成 (舰种={}, 卸下装备={})',
            [t.value for t in ship_types] if ship_types else '全部',
            remove_equipment,
        )
